package jobs

// The high-score port (T-023): a generic high-score page, rendered through the real
// pipeline (store, runner, Values, formatters, tmpl) from fixed sheet rows, must equal
// three golden files. The template and goldens are generic samples written for the
// project (T-080); the goldens were generated by this pipeline and checked by hand
// against the rendering rules (ADR 0002, ADR 0005, D-032):
//   - rows the template leaves out (6, 8, 9, 12, 14 and 23) are written as 40 spaces;
//   - rows 17-22 are blanked rather than omitted when there are fewer entries;
//   - rows 13, 15 and 16 are blanked when there is no entry;
//   - row 7 is held to 40 cells, so the name bar runs to cell 36;
//   - DE is the binding name;
//   - PN is the binding's page.

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"ceems/internal/store"
	"ceems/internal/tmpl"
)

// Colour cells a name bar is built from (editor palette codes).
const (
	cRed, cGreen, cYellow, cBlue, cWhite = "\x01", "\x02", "\x03", "\x04", "\x07"
	cNewBackground                       = "\x1d"
)

// hsGame is one row of the table in docs/highscores.md.
type hsGame struct {
	mpp          int
	name, rng, c string
	scoreFormat  string
	golden       string // golden file, "" when none
}

var hsGames = []hsGame{
	{0x401, "Rocket Rally", "C5:E", cBlue + cNewBackground + cYellow, "seconds", "P401.tti"},
	{0x402, "Turbo Track", "C4:E", "  " + cGreen, "number", "P402.tti"},
	{0x403, "Maze Muncher", "C4:E", cRed + cNewBackground + cWhite, "number", ""},
	{0x404, "Haunted Hall", "C4:E", cGreen + cNewBackground + cBlue, "number", ""},
	{0x405, "Robo Rumble", "C4:E", cBlue + cNewBackground + cWhite, "number", ""},
	{0x406, "Castle Quest Deluxe", "C4:E", cYellow + cNewBackground + cRed, "number", "P406.tti"},
}

// hsFixture is a sheet range: one leading incomplete row, then eight complete entries.
// Raw is what the API would give for the date column (a serial number or the text);
// the name and score formatters ignore it.
func hsFixture() Rows {
	entries := []struct {
		name, score, date string
		rawDate           any
	}{
		{"Longname-Player", "12.34", "09/12/2025", 46000.0},
		{"NINECHARS", "1,234", "08/12/2025", 45999.0},
		{"Bob", "999", "12/02/2025", 45700.0},
		{"Alice", "12,345,670", "27/07/2024", 45500.0},
		{"Cy", "1,000,000,000", "2025-10-12", "2025-10-12"},
		{"Eve", "123,456,789,012", "15/03/2023", 45000.0},
		{"Fay-Marie-Long", "50,000", "12/10/2025", "12/10/2025"},
		{"Gus", "123,456", "01/01/2021", 44197.0},
	}
	r := Rows{Formatted: [][]string{{"", "", ""}}, Raw: [][]any{{nil, nil, nil}}}
	for _, e := range entries {
		r.Formatted = append(r.Formatted, []string{e.name, e.score, e.date})
		r.Raw = append(r.Raw, []any{e.name, e.score, e.rawDate})
	}
	return r
}

// hsRender makes a store holding the template and one binding for g at mpp, runs it
// over the first n entries of the fixture and returns the stored page bytes.
func hsRender(t *testing.T, g hsGame, mpp, n int) []byte {
	t.Helper()
	db, err := store.Open(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { db.Close() })
	a := store.Audit{Actor: "user:1"}
	tid, err := db.CreateTemplate(&store.Template{Name: "High scores", TTI: hsTemplate(t), RowRules: `{"17":"p4name"}`}, a)
	if err != nil {
		t.Fatal(err)
	}
	source, _ := json.Marshal(map[string]any{
		"sheet": fakeSheetID, "range": g.rng, "columns": []string{"p#name", "p#scr", "p#date"}, "rows": 8,
		"format": map[string]string{"p#scr": g.scoreFormat, "p#date": "date"},
	})
	static, _ := json.Marshal(map[string]string{"c": g.c, "gname": g.name})
	id, err := db.CreateBinding(&store.Binding{Name: g.name, TemplateID: tid, MPP: mpp, Source: string(source), Static: string(static)}, a)
	if err != nil {
		t.Fatal(err)
	}
	fix := hsFixture()
	fix.Formatted, fix.Raw = fix.Formatted[:1+n], fix.Raw[:1+n]
	r := New(db, &funcSource{read: func(_ context.Context, sheet, rng string) (Rows, error) {
		if sheet != fakeSheetID || rng != g.rng {
			t.Errorf("Read(%d-byte sheet, %q), want range %q", len(sheet), rng, g.rng)
		}
		return fix, nil
	}}, slog.New(slog.NewTextHandler(&bytes.Buffer{}, nil)))
	r.now = func() time.Time { return time.Date(2026, 10, 12, 14, 5, 0, 0, time.Local) }
	if run, err := r.RunNow(t.Context(), id, "user:1"); err != nil || run.Outcome != "ok" {
		t.Fatalf("run %+v, %v", run, err)
	}
	p, err := db.Page(mpp)
	if err != nil {
		t.Fatal(err)
	}
	return p.TTI
}

func hsTemplate(t *testing.T) []byte {
	t.Helper()
	b, err := os.ReadFile(filepath.Join("..", "..", "testdata", "sample", "highscores", "template.tti"))
	if err != nil {
		t.Fatal(err)
	}
	return b
}

func hsGolden(t *testing.T, file string) []byte {
	t.Helper()
	b, err := os.ReadFile(filepath.Join("..", "..", "testdata", "sample", "highscores", "golden", file))
	if err != nil {
		t.Fatal(err)
	}
	return b
}

func TestHighScoreTemplateSlots(t *testing.T) {
	tp, err := tmpl.Parse(hsTemplate(t), map[string]string{"17": "p4name"})
	if err != nil {
		t.Fatal(err)
	}
	want := []string{
		"updated r3 c28 w12 left",
		"c r7 c1 w3 left",
		"gname r7 c4 w32 left",
		"p1name r13 c2 w9 centre", "p2name r13 c15 w9 centre", "p3name r13 c29 w9 centre",
		"p1scr r15 c2 w9 centre", "p2scr r15 c15 w9 centre", "p3scr r15 c29 w9 centre",
		"p1date r16 c2 w9 left", "p2date r16 c15 w9 left", "p3date r16 c29 w9 left",
	}
	for n := 4; n <= 8; n++ {
		row := 14 + n
		want = append(want,
			fmt.Sprintf("p%dname r%d c5 w9 left", n, row),
			fmt.Sprintf("p%dscr r%d c17 w9 left", n, row),
			fmt.Sprintf("p%ddate r%d c29 w9 left", n, row))
	}
	var got []string
	for _, s := range tp.Slots() {
		align := map[byte]string{0: "left", '^': "centre", '>': "right"}[s.Align]
		got = append(got, fmt.Sprintf("%s r%d c%d w%d %s", s.Name, s.Row, s.Col, s.Width, align))
	}
	if len(got) != 27 || strings.Join(got, "\n") != strings.Join(want, "\n") {
		t.Errorf("slots (%d):\n%s\nwant (%d):\n%s", len(got), strings.Join(got, "\n"), len(want), strings.Join(want, "\n"))
	}
	if b := hsTemplate(t); bytes.Count(b, []byte("\r\n")) == 0 || bytes.Count(b, []byte("\r\n")) != bytes.Count(b, []byte("\n")) {
		t.Error("template must use CRLF line endings throughout")
	}
}

func TestHighScoreGoldens(t *testing.T) {
	for _, c := range []struct {
		mpp, entries int
	}{{0x401, 3}, {0x402, 5}, {0x406, 8}} {
		g := hsGames[c.mpp-0x401]
		t.Run(g.golden, func(t *testing.T) {
			got, want := hsRender(t, g, g.mpp, c.entries), hsGolden(t, g.golden)
			if !bytes.Equal(got, want) {
				gl, wl := strings.Split(string(got), "\r\n"), strings.Split(string(want), "\r\n")
				for i := 0; i < len(gl) || i < len(wl); i++ {
					var a, b string
					if i < len(gl) {
						a = gl[i]
					}
					if i < len(wl) {
						b = wl[i]
					}
					if a != b {
						t.Errorf("line %d:\n got %q\nwant %q", i+1, a, b)
					}
				}
			}
		})
	}
}

// A game bound to a page outside magazine 4 renders the same bytes with its own PN.
func TestGameRendersOutsideMagazine4(t *testing.T) {
	g := hsGames[5]
	got := hsRender(t, g, 0x150, 8)
	want := bytes.Replace(hsGolden(t, "P406.tti"), []byte("PN,40600"), []byte("PN,15000"), 1)
	if !bytes.Equal(got, want) {
		t.Errorf("page 150 differs from P406 with PN 15000:\n got %q\nwant %q", got, want)
	}
}
